import java.nio.file.*;import java.time.*;import java.util.*;import jdk.jfr.consumer.*;
/** Streaming diagnostic summary; sampled allocation and CPU stacks are not retained bytes or exact method time. */
class JfrReport {
 static void add(Map<String,Long> m,String k,long n){m.merge(k,n,Long::sum);}
 static void print(java.io.Writer w,String label,Map<String,Long> m,int max)throws Exception{w.write(label+"\n");for(var e:m.entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(max).toList())w.write(e.getValue()+"\t"+e.getKey()+"\n");}
 public static void main(String[]args)throws Exception{for(String arg:args){var file=Path.of(arg);Map<String,Long> types=new TreeMap<>(),cpu=new HashMap<>(),mod=new HashMap<>(),alloc=new HashMap<>(),chunks=new HashMap<>(),network=new HashMap<>();long gc=0,pause=0,max=0;Instant first=null,last=null;double renderLoad=0,serverLoad=0,machineLoad=0,jvmLoad=0;int renderN=0,serverN=0,cpuN=0;try(var f=new RecordingFile(file)){while(f.hasMoreEvents()){var e=f.readEvent();var at=e.getStartTime();if(first==null||at.isBefore(first))first=at;if(last==null||at.isAfter(last))last=at;String type=e.getEventType().getName();add(types,type,1);if(type.equals("jdk.GarbageCollection")){gc++;long ns=e.getDuration("sumOfPauses").toNanos();pause+=ns;max=Math.max(max,e.getDuration("longestPause").toNanos());}if(type.equals("jdk.CPULoad")){machineLoad+=e.getFloat("machineTotal");jvmLoad+=e.getFloat("jvmUser")+e.getFloat("jvmSystem");cpuN++;}if(type.equals("jdk.ThreadCPULoad")){var thread=e.getThread();if(thread!=null){double load=e.getFloat("user")+e.getFloat("system");if(thread.getJavaName().equals("Render thread")){renderLoad+=load;renderN++;}if(thread.getJavaName().equals("Server thread")){serverLoad+=load;serverN++;}}}if(type.equals("jdk.ExecutionSample")){var t=e.getThread("sampledThread");String thread=t==null?"unknown":t.getJavaName();var st=e.getStackTrace();if(st!=null&&!st.getFrames().isEmpty()){var top=st.getFrames().getFirst().getMethod();add(cpu,thread+" | "+top.getType().getName()+"."+top.getName(),1);Set<String>seen=new HashSet<>();for(var frame:st.getFrames()){var m=frame.getMethod();String n=m.getType().getName()+"."+m.getName();if(n.startsWith("org.slavicmyths.")&&!n.contains("perf2")&&!n.contains("cubeaudit")&&seen.add(n))add(mod,thread+" | "+n,1);}}}if((type.equals("minecraft.PacketSent")||type.equals("minecraft.PacketReceived"))&&e.hasField("bytes"))add(network,type+" serialized_bytes",e.getLong("bytes"));if(type.equals("jdk.ObjectAllocationSample")){var st=e.getStackTrace();String site="unknown";if(st!=null&&!st.getFrames().isEmpty()){var m=st.getFrames().getFirst().getMethod();site=m.getType().getName()+"."+m.getName();}add(alloc,e.getClass("objectClass").getName()+" | "+site,e.getLong("weight"));}if(type.startsWith("minecraft.")&&type.toLowerCase().contains("chunk")&&e.getDuration()!=null)add(chunks,type,e.getDuration().toNanos());}}
 try(var out=Files.newBufferedWriter(file.resolveSibling(file.getFileName()+".report.tsv"))){out.write("profile_event_span_seconds\t"+Duration.between(first,last).toMillis()/1000.0+"\ngc_count\t"+gc+"\ngc_sum_pause_ms\t"+pause/1e6+"\ngc_max_pause_ms\t"+max/1e6+"\nrender_thread_jfr_cpu_load_mean_raw_fraction\t"+(renderN==0?"NOT_MEASURED":renderLoad/renderN)+"\nserver_thread_jfr_cpu_load_mean_raw_fraction\t"+(serverN==0?"NOT_MEASURED":serverLoad/serverN)+"\n");out.write("machine_cpu_total_mean_fraction\t"+(cpuN==0?"NOT_MEASURED":machineLoad/cpuN)+"\njvm_cpu_mean_fraction\t"+(cpuN==0?"NOT_MEASURED":jvmLoad/cpuN)+"\n");print(out,"EVENT_COUNTS",types,1000);print(out,"CPU_LEAF_SAMPLES (counts, not exact method milliseconds)",cpu,50);print(out,"MOD_INCLUSIVE_CPU_SAMPLES (overlap)",mod,50);print(out,"ALLOCATION_ESTIMATES_BYTES (sampling, not retained)",alloc,50);print(out,"CHUNK_EVENT_SUM_DURATION_NS (overlapping tasks, not wall throughput)",chunks,50);print(out,"RECORDED_NATIVE_PACKET_BYTES (integrated codec events, not wire traffic)",network,10);}
 }}
}
